arguments.prompt:
You are implementing a Blazor Web App for logistics shipment tracking. The project is already scaffolded at `/tmp/sv-699b8e2899f9459ab1a8ac3d40178483/ShipmentTracker/` with Interactive Auto, Global mode and Individual auth.

Project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - WebAssembly client project

The server Program.cs already has EF Core with SQLite, Identity, and all the Blazor wiring.

## What to implement

### 1. Shipment Entity (server project: `ShipmentTracker/Data/Shipment.cs`)

```csharp
namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public DateTime CreatedAt { get; set; }
    public string? CustomerEmail { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 2. Update ApplicationDbContext (server: `ShipmentTracker/Data/ApplicationDbContext.cs`)

Add `public DbSet<Shipment> Shipments => Set<Shipment>();` to the existing DbContext class.

### 3. Shared DTO and Service Interface (client project: `ShipmentTracker.Client/Services/`)

Create `ShipmentTracker.Client/Services/ShipmentDto.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime EstimatedDelivery { get; set; }
    public DateTime CreatedAt { get; set; }
    public string? CustomerEmail { get; set; }
}
```

Create `ShipmentTracker.Client/Services/IShipmentService.cs`:
```csharp
namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<ShipmentDto>> GetAllShipmentsAsync();
    Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber);
    Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment);
    Task UpdateStatusAsync(int id, string status);
}
```

Create `ShipmentTracker.Client/Services/ClientShipmentService.cs`:
```csharp
using System.Net.Http.Json;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public ClientShipmentService(HttpClient http) => _http = http;

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        var response = await _http.PutAsync($"api/shipments/{id}/status?status={Uri.EscapeDataString(status)}", null);
        response.EnsureSuccessStatusCode();
    }
}
```

### 4. Server-side service implementation (server project: `ShipmentTracker/Services/ServerShipmentService.cs`)

```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ServerShipmentService(ApplicationDbContext db) => _db = db;

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await _db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpperInvariant()}",
            Description = dto.Description,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = ShipmentStatus.Pending,
            EstimatedDelivery = dto.EstimatedDelivery,
            CreatedAt = DateTime.UtcNow,
            CustomerEmail = dto.CustomerEmail
        };

        _db.Shipments.Add(shipment);
        await _db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        var shipment = await _db.Shipments.FindAsync(id);
        if (shipment is null) return;

        if (Enum.TryParse<ShipmentStatus>(status, true, out var parsed))
        {
            shipment.Status = parsed;
            await _db.SaveChangesAsync();
        }
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Description = s.Description,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        EstimatedDelivery = s.EstimatedDelivery,
        CreatedAt = s.CreatedAt,
        CustomerEmail = s.CustomerEmail
    };
}
```

### 5. API Endpoints — add to server Program.cs

Add these lines BEFORE `app.Run();` in the server `Program.cs`:

```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments");

shipments.MapGet("/", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var result = await service.GetByTrackingNumberAsync(trackingNumber);
    return result is null ? Results.NotFound() : Results.Ok(result);
}).RequireAuthorization();

shipments.MapPost("/", async (ShipmentDto dto, IShipmentService service) =>
{
    var created = await service.CreateShipmentAsync(dto);
    return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
}).RequireAuthorization();

shipments.MapPut("/{id}/status", async (int id, string status, IShipmentService service) =>
{
    await service.UpdateStatusAsync(id, status);
    return Results.NoContent();
}).RequireAuthorization();
```

Also add `using ShipmentTracker.Client.Services;` and `using ShipmentTracker.Services;` at the top of server Program.cs, and register services:
After `builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();` add:
```csharp
builder.Services.AddScoped<IShipmentService, ServerShipmentService>();
```

### 6. Client Program.cs — register HttpClient and service

Replace the client `ShipmentTracker.Client/Program.cs` with:
```csharp
using Microsoft.AspNetCore.Components.WebAssembly.Hosting;
using ShipmentTracker.Client.Services;

var builder = WebAssemblyHostBuilder.CreateDefault(args);

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp => new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ClientShipmentService>();

await builder.Build().RunAsync();
```

### 7. Pages in Client project

Delete the template pages: `Counter.razor`, `Weather.razor` from `ShipmentTracker.Client/Pages/`. Keep `Home.razor`, `Auth.razor`, and `NotFound.razor`.

Replace `Home.razor` with a simple landing page:
```razor
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>
<p class="lead">Track and manage your shipments worldwide.</p>

<div class="row mt-4">
    <div class="col-md-6 mb-3">
        <div class="card h-100">
            <div class="card-body">
                <h5 class="card-title">📦 Track a Shipment</h5>
                <p class="card-text">Enter your tracking number to check the current status and estimated delivery date.</p>
                <a href="track" class="btn btn-primary">Track Now</a>
            </div>
        </div>
    </div>
    <div class="col-md-6 mb-3">
        <div class="card h-100">
            <div class="card-body">
                <h5 class="card-title">🚚 Dispatcher Dashboard</h5>
                <p class="card-text">View all shipments, update statuses, and create new shipments.</p>
                <a href="shipments" class="btn btn-secondary">Go to Dashboard</a>
            </div>
        </div>
    </div>
</div>
```

Create `ShipmentTracker.Client/Pages/Shipments.razor` (dispatcher dashboard):
```razor
@page "/shipments"
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService
@attribute [Microsoft.AspNetCore.Authorization.Authorize]

<PageTitle>Shipments - Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3">
    <button class="btn btn-success" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreate)
{
    <div class="card mb-4">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input @bind="newShipment.Description" class="form-control" placeholder="Description" />
                </div>
                <div class="col-md-2">
                    <input @bind="newShipment.Origin" class="form-control" placeholder="Origin" />
                </div>
                <div class="col-md-2">
                    <input @bind="newShipment.Destination" class="form-control" placeholder="Destination" />
                </div>
                <div class="col-md-2">
                    <input @bind="newShipment.CustomerEmail" class="form-control" placeholder="Customer Email" />
                </div>
                <div class="col-md-2">
                    <input type="date" @bind="newShipment.EstimatedDelivery" class="form-control" />
                </div>
                <div class="col-md-1">
                    <button class="btn btn-primary" @onclick="CreateShipment">Add</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <div class="mb-3">
        <input @bind="filterText" @bind:event="oninput" class="form-control" placeholder="Filter by destination or tracking number..." style="max-width: 400px;" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Description</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Description</td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                value="@s.Status" @onchange="e => UpdateStatus(s, e.Value?.ToString())">
                            <option value="Pending">Pending</option>
                            <option value="PickedUp">Picked Up</option>
                            <option value="InTransit">In Transit</option>
                            <option value="OutForDelivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                            <option value="Delayed">Delayed</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool showCreate;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(7) };
    private string filterText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrWhiteSpace(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreate = !showCreate;

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Description)) return;

        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Insert(0, created);
        newShipment = new() { EstimatedDelivery = DateTime.Now.AddDays(7) };
        showCreate = false;
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (string.IsNullOrWhiteSpace(newStatus) || newStatus == shipment.Status) return;
        await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
        shipment.Status = newStatus;
    }

    private static string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };
}
```

