Create `ShipmentTracker.Client/Services/ClientShipmentService.cs`:
```csharp
using System.Net.Http.Json;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public ClientShipmentService(HttpClient http) => _http = http;

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments") ?? [];
    }

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode) return null;
        return await response.Content.ReadFromJsonAsync<ShipmentDto>();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await _http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<ShipmentDto>())!;
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        var response = await _http.PutAsync($"api/shipments/{id}/status?status={Uri.EscapeDataString(status)}", null);
        response.EnsureSuccessStatusCode();
    }
}
```

### 4. Server-side service implementation (server project: `ShipmentTracker/Services/ServerShipmentService.cs`)

```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ServerShipmentService(ApplicationDbContext db) => _db = db;

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _db.Shipments
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await _db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var shipment = new Shipment
        {
            TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpperInvariant()}",
            Description = dto.Description,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = ShipmentStatus.Pending,
            EstimatedDelivery = dto.EstimatedDelivery,
            CreatedAt = DateTime.UtcNow,
            CustomerEmail = dto.CustomerEmail
        };

        _db.Shipments.Add(shipment);
        await _db.SaveChangesAsync();
        return ToDto(shipment);
    }

    public async Task UpdateStatusAsync(int id, string status)
    {
        var shipment = await _db.Shipments.FindAsync(id);
        if (shipment is null) return;

        if (Enum.TryParse<ShipmentStatus>(status, true, out var parsed))
        {
            shipment.Status = parsed;
            await _db.SaveChangesAsync();
        }
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Description = s.Description,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        EstimatedDelivery = s.EstimatedDelivery,
        CreatedAt = s.CreatedAt,
        CustomerEmail = s.CustomerEmail
    };
}
```

### 5. API Endpoints — add to server Program.cs

Add these lines BEFORE `app.Run();` in the server `Program.cs`:

```csharp
// Shipment API endpoints
var shipments = app.MapGroup("api/shipments");

shipments.MapGet("/", async (IShipmentService service) =>
    Results.Ok(await service.GetAllShipmentsAsync()))
    .RequireAuthorization();

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
{
    var result = await service.GetByTrackingNumberAsync(trackingNumber);
    return result is null ? Results.NotFound() : Results.Ok(result);
}).RequireAuthorization();

shipments.MapPost("/", async (ShipmentDto dto, IShipmentService service) =>
{
    var created = await service.CreateShipmentAsync(dto);
    return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
}).RequireAuthorization();

shipments.MapPut("/{id}/status", async (int id, string status, IShipmentService service) =>
{
    await service.UpdateStatusAsync(id, status);
    return Results.NoContent();
}).RequireAuthorization();
```

